 using System.IO;
 using System.Runtime.CompilerServices;

 namespace ABLogixGitManager.Services;

 /// <summary>
 /// Thread-safe, file-based diagnostic logger for the application.
 /// Writes structured log lines to <c>%APPDATA%\ABLogixGitManager\logs\app-YYYY-MM-DD.log</c>.
 /// The log file rotates daily (one file per calendar day).
 /// </summary>
 /// <remarks>
 /// <para>
 /// This logger is intentionally simple and has no external dependencies.
 /// It silently discards I/O failures so a logging error never masks the
 /// original problem being diagnosed.
 /// </para>
 /// <para>
 /// Log line format:
 /// <code>
 /// 2026-07-24 12:34:56.789 [INFO ] [MethodName] message text
 /// 2026-07-24 12:34:56.789 [ERROR] [MethodName] Short description
 ///   Exception: ExceptionType: message
 ///   Stack:
 ///     at ...
 /// </code>
 /// </para>
 /// </remarks>
 public static class AppLogger
 {
     private static readonly string LogDir = Path.Combine(
         Environment.GetFolderPath(Environment.SpecialFolder.ApplicationData),
         "ABLogixGitManager",
         "logs");

     // Computed once per process start; file rotates on next launch if day changes.
     private static readonly string _logFilePath = Path.Combine(
         LogDir, $"app-{DateTime.Now:yyyy-MM-dd}.log");

     private static readonly object _fileLock = new();

     /// <summary>Gets the full path of the active log file for this session.</summary>
     public static string FilePath => _logFilePath;

     // -------------------------------------------------------------------------
     // Public logging methods
     // -------------------------------------------------------------------------

     /// <summary>Logs an informational message.</summary>
     /// <param name="message">The message to log.</param>
     /// <param name="caller">Automatically populated with the calling method name.</param>
     public static void Info(string message, [CallerMemberName] string? caller = null)
         => Write("INFO ", message, null, caller);

     /// <summary>Logs a warning message indicating a potentially unexpected condition.</summary>
     /// <param name="message">The message to log.</param>
     /// <param name="caller">Automatically populated with the calling method name.</param>
     public static void Warn(string message, [CallerMemberName] string? caller = null)
         => Write("WARN ", message, null, caller);

     /// <summary>
     /// Logs an error message, optionally including full exception details
     /// (type, message, and stack trace).
     /// </summary>
     /// <param name="message">Short description of what failed.</param>
     /// <param name="ex">The exception to include, or <c>null</c> for a message-only error.</param>
     /// <param name="caller">Automatically populated with the calling method name.</param>
     public static void Error(string message, Exception? ex = null, [CallerMemberName] string? caller = null)
         => Write("ERROR", message, ex, caller);

     // -------------------------------------------------------------------------
     // Private implementation
     // -------------------------------------------------------------------------

     private static void Write(string level, string message, Exception? ex, string? caller)
     {
         var ts = DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss.fff");
         var callerPart = caller is not null ? $" [{caller}]" : string.Empty;
         var body = ex is null
             ? message
             : $"{message}\n  Exception: {ex.GetType().Name}: {ex.Message}\n  Stack:\n{IndentStack(ex.StackTrace)}";

         var line = $"{ts} [{level}]{callerPart} {body}";

         try
         {
             Directory.CreateDirectory(LogDir);
             lock (_fileLock)
                 File.AppendAllText(_logFilePath, line + Environment.NewLine);
         }
         catch
         {
             // Never throw from the logger — silently discard all I/O failures.
         }
     }

     private static string IndentStack(string? stack)
     {
         if (stack is null) return "    (no stack trace)";
         return string.Join(
             Environment.NewLine,
             stack.Split('\n').Select(l => "    " + l.TrimEnd()));
     }
 }

